// ── Default items (used as seed in the builder) ────────────────────────────

export const DEFAULT_PROGRAM_ITEMS: ProgramItem[] = [
  { id: "p1", time: "13:00", title: "Aankomst",  description: "Welkom bij onze trouwdag",  iconId: "welkom"  },
  { id: "p2", time: "14:00", title: "Ceremonie", description: "Het ja-woord moment",        iconId: "ringen"  },
  { id: "p3", time: "17:00", title: "Borrel",    description: "Toasten op het geluk",       iconId: "toost"   },
  { id: "p4", time: "19:00", title: "Diner",     description: "Geniet van het feestmaal",   iconId: "cutlery" },
  { id: "p5", time: "22:00", title: "Feest",     description: "Dansen tot in de nacht",     iconId: "feest"   },
]

// ── Component ──────────────────────────────────────────────────────────────
// Eén indeling: de getekende tijdlijn (ontwerpronde, 2 oktober 2026). Een
// dunne lijn in de accentkleur tekent zichzelf terwijl je scrolt; op de lijn
// de iconen in een rondje, de tijd groot in het titellettertype, de tekst
// ernaast. Op desktop om en om links en rechts, op de telefoon alles rechts.
// Op de trouwdag licht het onderdeel op dat nu bezig is.

interface Props {
  items: ProgramItem[]
  sc: SC
  /** De trouwdag (JJJJ-MM-DD); op die dag licht het onderdeel op dat nu bezig is */
  datum?: string | null
  /** Van vroeger; er is nog één indeling */
  programLayout?: ProgramLayout
  builderMode?: boolean
  onImagePositionChange?: (id: string, x: number, y: number) => void
  onItemClick?: (itemId: string, field?: 'title' | 'description') => void
}

function minuten(t: string): number {
  const [h, m] = t.split(":").map(Number)
  return (h || 0) * 60 + (m || 0)
}

function vandaagIso(): string {
  const d = new Date()
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`
}

export default function EventProgramPreview({ items, sc, datum, builderMode, onItemClick }: Props) {
  const locale = useUILocale()
  const sorted = items.slice().sort((a, b) => a.time.localeCompare(b.time))

  // Welk onderdeel nu bezig is, alleen op de dag zelf
  const [nuIdx, setNuIdx] = useState(-1)
  useEffect(() => {
    if (builderMode || !datum) return
    const bepaal = () => {
      if (vandaagIso() !== datum.slice(0, 10)) { setNuIdx(-1); return }
      const n = new Date()
      const nu = n.getHours() * 60 + n.getMinutes()
      let idx = -1
      sorted.forEach((it, i) => { if (it.time && minuten(it.time) <= nu) idx = i })
      setNuIdx(idx)
    }
    bepaal()
    const t = setInterval(bepaal, 60_000)
    return () => clearInterval(t)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [builderMode, datum, items])

  // De lijn tekent zichzelf: zo ver als de pagina gescrold is
  const vak = useRef<HTMLDivElement>(null)
  const [deel, setDeel] = useState(builderMode ? 1 : 0)
  useEffect(() => {
    if (builderMode) return
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) { setDeel(1); return }
    const meet = () => {
      const el = vak.current
      if (!el) return
      const r = el.getBoundingClientRect()
      setDeel(Math.min(1, Math.max(0, (window.innerHeight * 0.85 - r.top) / r.height)))
    }
    meet()
    window.addEventListener("scroll", meet, { passive: true })
    window.addEventListener("resize", meet)
    return () => { window.removeEventListener("scroll", meet); window.removeEventListener("resize", meet) }
  }, [builderMode])

  // De lijn loopt van het midden van het eerste rondje tot het midden van het
  // laatste. Eerst liep hij over het hele vak en stak hij boven het eerste en
  // onder het laatste onderdeel uit (Michiel, 10 oktober 2026). Gemeten aan de
  // rondjes zelf, want die zijn op de desktop groter dan op de telefoon.
  const [lijnPlek, setLijnPlek] = useState({ top: 36, bottom: 36 })
  useEffect(() => {
    const el = vak.current
    if (!el) return
    const meet = () => {
      const rondjes = el.querySelectorAll<HTMLElement>("[data-rondje]")
      const eerste = rondjes[0]
      const laatste = rondjes[rondjes.length - 1]
      if (!eerste || !laatste) return
      // Met offsetTop in plaats van de plek op het scherm: in de bouwer is het
      // voorbeeld verkleind en tijdens het invaden even kleiner, en dan
      // klopte de meting niet met de echte maat (Michiel, 11 oktober 2026)
      const midden = (r: HTMLElement) => {
        let y = r.offsetHeight / 2
        let n: HTMLElement | null = r
        while (n && n !== el) { y += n.offsetTop; n = n.offsetParent as HTMLElement | null }
        return y
      }
      setLijnPlek({ top: Math.round(midden(eerste)), bottom: Math.max(0, Math.round(el.clientHeight - midden(laatste))) })
    }
    meet()
    const ro = new ResizeObserver(meet)
    ro.observe(el)
    return () => ro.disconnect()
  }, [items])

  const lijnKlas = "absolute left-[32px] @md:left-1/2"

  return (
    <div className="@container" style={{ fontFamily: sc.fontFamily }}>
      <div style={{ padding: "48px 20px 64px" }}>
        <SectieKop sc={sc} kopje="De dag" titel={<span className="notranslate">{getUILabel(locale, "programma")}</span>} />
        <div ref={vak} className="relative mx-auto" style={{ maxWidth: 840 }}>
          <div aria-hidden="true" className={lijnKlas} style={{ ...lijnPlek, width: 1, marginLeft: -0.5, backgroundColor: `${sc.accent}2e` }} />
          <div aria-hidden="true" className={lijnKlas} style={{ ...lijnPlek, width: 1, marginLeft: -0.5, backgroundColor: sc.accent,transformOrigin: "top", transform: `scaleY(${deel})`, transition: "transform 0.25s linear" }} />

          {sorted.map((item, i) => {
            const rechts = i % 2 === 1
            const nu = i === nuIdx
            const id = item.id ?? `${item.time}::${item.description}`
            const laatste = i === sorted.length - 1
            // In de bouwer klik je op de tekst om hem te bewerken. De stijl
            // komt er apart bij: eerst verving de klik de hele style, en dan
            // stond de tekst in de standaardkleur, bij Noir onzichtbaar
            // (Michiel, 2 oktober 2026)
            const klik = (veld: 'title' | 'description') => onItemClick && item.id
              ? { onClick: () => onItemClick(item.id!, veld), title: "Klik om te bewerken" }
              : {}
            const wijs = onItemClick && item.id ? { cursor: "pointer" as const } : {}
            return (
              <div key={id} data-onderdeel className="group relative grid grid-cols-[64px_1fr] @md:grid-cols-[1fr_96px_1fr] items-start" style={{ paddingBottom: laatste ? 0 : 36 }}>
                {/* Het rondje op de lijn, met het icoon of een fotootje. Op de
                    desktop groter: 80 in plaats van 64, met een icoon van 52
                    (Michiel, 10 oktober 2026). */}
                <div className="flex justify-center @md:col-start-2 @md:row-start-1" style={{ paddingTop: 4 }}>
                  <div
                    data-rondje
                    // Met de muis over een onderdeel: het rondje wordt iets
                    // groter en krijgt een zachte ring (Michiel, 10 oktober
                    // 2026). Alleen met een muis; op de telefoon blijft het stil.
                    className="w-16 h-16 @md:w-20 @md:h-20 group-hover:scale-110 group-hover:shadow-[0_0_0_6px_var(--rond-ring)]"
                    style={{
                      "--rond-ring": `${sc.accent}26`,
                      borderRadius: "50%", flexShrink: 0, overflow: "hidden",
                      backgroundColor: nu ? sc.accent : sc.bodyBg,
                      border: `1.5px solid ${sc.accent}`,
                      boxShadow: nu ? `0 0 0 7px ${sc.accent}30` : undefined,
                      display: "flex", alignItems: "center", justifyContent: "center",
                      color: nu ? sc.buttonText : sc.accent,
                      transition: "background-color 0.4s ease, box-shadow 0.3s ease, transform 0.3s ease",
                    } as CSSProperties}
                  >
                    {item.image_url ? (
                      // eslint-disable-next-line @next/next/no-img-element
                      <img src={item.image_url} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: `${item.imagePosX ?? 50}% 50%` }} />
                    ) : (
                      <ProgramIcon iconId={item.iconId} size={42 /* was 34, Michiel wilde ze groter (10 oktober 2026) */} strokeWidth={1.5} className="@md:w-auto @md:h-[52px]" />
                    )}
                  </div>
                </div>

                {/* De tekst: op de telefoon rechts van de lijn, op desktop om en om */}
                <div className={`min-w-0 pl-3 @md:pl-0 @md:row-start-1 ${rechts ? "@md:col-start-3 @md:pl-7 @md:text-left" : "@md:col-start-1 @md:pr-7 @md:text-right"}`} style={{ paddingTop: 10 }}>
                  {nu && (
                    <span style={{ display: "block", fontSize: "0.6875rem", fontWeight: 700, letterSpacing: "0.22em", textTransform: "uppercase", color: sc.accent, marginBottom: 4 }}>Nu</span>
                  )}
                  {item.time && (
                    <p style={{ margin: 0, fontFamily: sc.fontPageTitles, fontWeight: sc.fontPageTitlesWeight, fontSize: "1.75rem", lineHeight: 1, color: sc.accent, fontVariantNumeric: "tabular-nums" }}>
                      {item.time}
                    </p>
                  )}
                  {item.title && (
                    <p className="break-words" style={{ margin: "8px 0 2px", fontWeight: 700, fontSize: "1.125rem", lineHeight: 1.3, color: sc.headingColor, ...wijs }} {...klik('title')}>
                      {item.title}
                    </p>
                  )}
                  {item.description && (
                    <p className="break-words whitespace-pre-wrap" style={{ margin: 0, fontSize: "0.9375rem", lineHeight: 1.6, color: sc.bodyText, ...wijs }} {...klik('description')}>
                      {item.description}
                    </p>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}
